import{describe,it,expect}from"vitest";import{parseSeasonRanges,computeSeasonalFit,getFestivalsForMonth,SeasonalRecommendationEngine}from"../../frontend/js-modules/seasonal-recommendation-engine.js";const destinations=[{id:"agra",name:"Agra",state:"Uttar Pradesh",categories:["historical","heritage"],bestSeason:"Oct-Mar",popularity:10},{id:"manali",name:"Manali",state:"Himachal Pradesh",categories:["mountains","adventure"],bestSeason:"Mar-Jun, Sep-Dec",popularity:8},{id:"goa",name:"Goa",state:"Goa",categories:["beaches"],bestSeason:"Nov-Feb",popularity:9},{id:"jaisalmer",name:"Jaisalmer",state:"Rajasthan",categories:["desert","historical","adventure"],bestSeason:"Nov-Feb",popularity:8},{id:"no-data-dest",name:"Mystery Town",state:"Nowhere",categories:["heritage"],bestSeason:"",popularity:3}],events=[{id:"taj-mahotsav",name:"Taj Mahotsav",destinationId:"agra",state:"Uttar Pradesh",startMonth:2,endMonth:2,popularity:7},{id:"pushkar-camel-fair",name:"Pushkar Camel Fair",destinationId:"jaisalmer",state:"Rajasthan",startMonth:10,endMonth:11,popularity:8},{id:"goa-carnival",name:"Goa Carnival",destinationId:"goa",state:"Goa",startMonth:2,endMonth:2,popularity:9}];describe("parseSeasonRanges",()=>{it("parses a single month range",()=>{expect(parseSeasonRanges("Oct-Mar")).toEqual([{start:10,end:3}])}),it("parses multiple comma-separated ranges",()=>{expect(parseSeasonRanges("Mar-Jun, Sep-Dec")).toEqual([{start:3,end:6},{start:9,end:12}])}),it("returns an empty array for empty/malformed input",()=>{expect(parseSeasonRanges("")).toEqual([]),expect(parseSeasonRanges(void 0)).toEqual([]),expect(parseSeasonRanges("not-a-range-format-xyz")).toEqual([])})}),describe("computeSeasonalFit",()=>{it("marks a month inside the best-season window as ideal",()=>{const e=computeSeasonalFit(destinations[0],12);expect(e.level).toBe("ideal"),expect(e.score).toBe(1)}),it("marks a month just outside the window as shoulder season",()=>{const e=computeSeasonalFit(destinations[2],3);expect(e.level).toBe("shoulder")}),it("marks a month far outside the window as off-season",()=>{const e=computeSeasonalFit(destinations[2],7);expect(e.level).toBe("off-season"),expect(e.score).toBeLessThan(.5)}),it("handles a wrap-around range correctly across the year boundary",()=>{expect(computeSeasonalFit(destinations[2],1).level).toBe("ideal"),expect(computeSeasonalFit(destinations[2],12).level).toBe("ideal"),expect(computeSeasonalFit(destinations[2],6).level).toBe("off-season")}),it("returns 'unknown' with a neutral score when there is no season data",()=>{const e=computeSeasonalFit(destinations[4],6);expect(e.level).toBe("unknown"),expect(e.score).toBe(.5)})}),describe("getFestivalsForMonth",()=>{it("finds festivals matching destinationId and month",()=>{const e=getFestivalsForMonth(destinations[0],2,events);expect(e.map(e=>e.id)).toEqual(["taj-mahotsav"])}),it("returns an empty array when nothing matches",()=>{expect(getFestivalsForMonth(destinations[0],7,events)).toEqual([])}),it("sorts multiple matches by popularity descending",()=>{const e=[...events,{id:"extra-goa-event",name:"Extra Goa Event",destinationId:"goa",state:"Goa",startMonth:2,endMonth:2,popularity:15}],t=getFestivalsForMonth(destinations[2],2,e);expect(t[0].id).toBe("extra-goa-event")})}),describe("SeasonalRecommendationEngine.recommend",()=>{it("throws for an invalid month",()=>{const e=new SeasonalRecommendationEngine({destinations:destinations,events:events});expect(()=>e.recommend({month:13})).toThrow(),expect(()=>e.recommend({month:0})).toThrow()}),it("ranks destinations that are in-season for the given month above off-season ones",()=>{const e=new SeasonalRecommendationEngine({destinations:destinations,events:events}).recommend({month:12}).map(e=>e.destination.id);expect(e.indexOf("agra")).toBeLessThan(e.indexOf("no-data-dest"))}),it("filters to only destinations matching requested interests when interests are given",()=>{const e=new SeasonalRecommendationEngine({destinations:destinations,events:events}).recommend({month:12,interests:["beaches"]});expect(e.every(e=>e.destination.categories.includes("beaches"))).toBe(!0),expect(e.map(e=>e.destination.id)).toContain("goa")}),it("includes matching festivals in the result and explanation",()=>{const e=new SeasonalRecommendationEngine({destinations:destinations,events:events}).recommend({month:2}).find(e=>"agra"===e.destination.id);expect(e.festivals.map(e=>e.id)).toContain("taj-mahotsav"),expect(e.explanation).toMatch(/Taj Mahotsav/)}),it("respects the limit parameter",()=>{const e=new SeasonalRecommendationEngine({destinations:destinations,events:events}).recommend({month:12,limit:2});expect(e.length).toBeLessThanOrEqual(2)})}),describe("SeasonalRecommendationEngine.getAlternatives",()=>{it("returns no alternatives when the destination is already an ideal fit",()=>{const e=new SeasonalRecommendationEngine({destinations:destinations,events:events}).getAlternatives(destinations[2],12);expect(e).toEqual([])}),it("suggests a same-category, in-season alternative for an off-season destination",()=>{const e=new SeasonalRecommendationEngine({destinations:destinations,events:events}),t=e.getAlternatives(destinations[2],7);expect(t).toEqual([]);const n=e.getAlternatives(destinations[3],1);expect(n).toEqual([])}),it("never suggests the destination as its own alternative",()=>{const e=new SeasonalRecommendationEngine({destinations:destinations,events:events}).getAlternatives(destinations[2],7);expect(e.every(e=>e.destination.id!==destinations[2].id)).toBe(!0)})});